import { Button, Select, Switch, Alert } from '@jinx-ui/react';

type Role = 'member' | 'admin' | 'viewer';

const ROLE_OPTIONS: { value: Role; label: string }[] = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = useMemo(() => EMAIL_PATTERN.test(email.trim()), [email]);
  const showError = touched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid && email.length > 0;

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <div className="jx-stack" style={{ maxWidth: 420, gap: 'var(--jx-space-4)' }}>
      {submitted && (
        <Alert tone="success" onDismiss={() => setSubmitted(false)}>
          Приглашение отправлено на {email}
        </Alert>
      )}

      <form className="jx-card jx-stack" style={{ padding: 'var(--jx-space-5)', gap: 'var(--jx-space-4)' }} onSubmit={handleSubmit}>
        <h2 className="jx-heading">Пригласить в команду</h2>

        <div className="jx-field">
          <label className="jx-label" htmlFor="invite-email">
            Email
          </label>
          <input
            id="invite-email"
            type="email"
            className={showError ? 'jx-input jx-input--invalid' : 'jx-input'}
            placeholder="name@company.com"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            onBlur={() => setTouched(true)}
            aria-invalid={showError}
            aria-describedby="invite-email-hint"
            required
          />
          <p
            id="invite-email-hint"
            className={showError ? 'jx-field-error' : 'jx-field-hint'}
            role={showError ? 'alert' : undefined}
          >
            {showError ? 'Введите корректный email-адрес' : 'Мы отправим приглашение на эту почту'}
          </p>
        </div>

        <div className="jx-field">
          <label className="jx-label" htmlFor="invite-role">
            Роль
          </label>
          <Select
            id="invite-role"
            value={role}
            onValueChange={(value) => setRole(value as Role)}
          >
            {ROLE_OPTIONS.map((option) => (
              <Select.Option key={option.value} value={option.value}>
                {option.label}
              </Select.Option>
            ))}
          </Select>
        </div>

        <div className="jx-field jx-field--row">
          <label className="jx-label" htmlFor="invite-notify">
            Отправить уведомление
          </label>
          <Switch
            id="invite-notify"
            checked={notify}
            onCheckedChange={setNotify}
          />
        </div>

        <Button type="submit" disabled={!canSubmit}>
          Отправить приглашение
        </Button>
      </form>
    </div>
  );
}

